ddl_sample:
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies WHERE tablename = 'traces' AND policyname = 'tenant_isolation_policy'
    ) THEN
        CREATE POLICY tenant_isolation_policy ON traces
        AS RESTRICTIVE
        USING (project_id = NULLIF(current_setting('app.current_project_id', true), ''))
        WITH CHECK (project_id = NULLIF(current_setting('app.current_project_id', true), ''));
    END IF;
END $$;
